            if ingest_run_id and ingest_col in dq_df.columns:
                dq_df = dq_df.where(F.col(ingest_col) == F.lit(ingest_run_id))
            resolved_keys = resolve_df_key_cols(dq_df, key_cols, f"{target_name} table {table_name}")
