    default_layers = ["BR", "SL", "GL"]
    raw = p_active_target_layers_json
    if raw is None:
        layers = default_layers
    elif isinstance(raw, list):
        layers = raw
    else:
        text = str(raw).strip()
        if not text or text.upper() == "NULL":
            layers = default_layers
        elif text.startswith("["):
            layers = json.loads(text)
        else:
            layers = [item.strip() for item in text.split(",") if item.strip()]

    normalized = []
    for layer in layers:
        layer_name = str(layer).upper().strip()
        if layer_name and layer_name not in normalized:
            normalized.append(layer_name)

    valid_layers = {"BR", "SL", "GL"}
    invalid_layers = [layer for layer in normalized if layer not in valid_layers]
    if invalid_layers:
        raise Exception(f"Unsupported target layer(s): {invalid_layers}. Supported layers: BR, SL, GL")
    if "BR" not in normalized:
        raise Exception("Active target layers must include BR")
    return normalized

ACTIVE_TARGET_LAYERS = parse_active_target_layers()
