        audit_offset_base=100
    )

    append_dataquality_for_layer(br, "BR", reference_layer=sl, ingest_run_id=p_ingest_run_id)

    for layer_idx, target_name in enumerate(ACTIVE_TARGET_LAYERS[1:], start=1):
        layer = layers[target_name]
        append_dataquality_for_layer(layer, target_name)
        finish_layer_tasks(
            layer,
            target_name,
            p_ingest_run_id,
            status="SUCCESS",
            log_level="INFO",
            error_message=None,
            audit_offset_base=300 + ((layer_idx - 1) * 100),
            br_layer=br,
            sl_layer=sl
        )

    exit_json({
        "status": "OK",
        "mode": mode,
        "target_layers": ACTIVE_TARGET_LAYERS,
        "terminal_target": TERMINAL_TARGET_NAME,
        "bronze_tasks": len(layer_tasks(br)),
        "silver_tasks": len(layer_tasks(sl)) if sl else 0,
        "gold_tasks": len(layer_tasks(layers.get("GL"))) if layers.get("GL") else 0,
        "bronze_rows": int(bronze_rows)
    })

elif mode in ("FINALIZE_FAILURE", "FINALIZE_NOTES_FAILURE"):
    layers = context_for_active_targets(ctx, mode)
    br = layers["BR"]
    sl = layers.get("SL")

    if not p_ingest_run_id:
        raise Exception(f"p_ingest_run_id is required for {mode}")

    failed_target = (p_failed_target_name or "ALL").upper()
    fail_all_layers = failed_target in ("ALL", "UNKNOWN", "AUTO")
    valid_failure_targets = set(ACTIVE_TARGET_LAYERS + ["ALL", "UNKNOWN", "AUTO"])
    if failed_target not in valid_failure_targets:
        failed_target = "ALL"
        fail_all_layers = True

    failure_message = (
        p_error_message
        or f"{p_config_name_prefix} pipeline failed. Check the failed parent/child activity run details."
    )

    method_results = parse_method_results_json(p_method_results_json, p_silver_method_results_json)
    if method_results:
        finish_bronze_tasks_from_method_results(
            br,
            method_results,
            p_ingest_run_id,
            audit_offset_base=500
        )

        try:
            append_dataquality_for_layer(br, "BR", reference_layer=sl, ingest_run_id=p_ingest_run_id)
        except Exception as exc:
            print(f"BR DQ warning: {exc}")

        for layer_idx, target_name in enumerate(ACTIVE_TARGET_LAYERS[1:], start=1):
            layer = layers[target_name]
            finish_layer_tasks_from_method_results(
                layer,
                target_name,
                method_results,
                p_ingest_run_id,
                audit_offset_base=600 + ((layer_idx - 1) * 100),
                br_layer=br,
                sl_layer=sl
            )
            has_success = any(
                is_success_status(result_for_method(method_results, task_method(task)).get("status"))
                for task in layer_tasks(layer)
            )
            if has_success:
                try:
                    append_dataquality_for_layer(layer, target_name)
                except Exception as exc:
                    print(f"{target_name} DQ warning: {exc}")

        payload = {
            "status": "FAILED",
            "mode": mode,
            "failed_target": failed_target,
            "target_layers": ACTIVE_TARGET_LAYERS,
            "terminal_target": TERMINAL_TARGET_NAME,
            "failure_activity": p_failure_activity,
            "message": "Partial/site-level failure audit finalized; raising exception to keep pipeline failed."
        }
        print(json.dumps(payload))
        raise Exception(json.dumps(payload))

    target_order = ACTIVE_TARGET_LAYERS
    failed_idx = 0 if fail_all_layers else target_order.index(failed_target)

    for idx, target_name in enumerate(target_order):
        layer = layers[target_name]
        if fail_all_layers:
            final_status = "FAILED"
            log_level = "ERROR"
            err = failure_message
        elif idx < failed_idx:
            final_status = "SUCCESS"
            log_level = "INFO"
            err = None
        elif idx == failed_idx:
            final_status = "FAILED"
            log_level = "ERROR"
            err = failure_message
        else:
            final_status = "SKIPPED"
            log_level = "WARN"
            err = f"Skipped because {failed_target} failed"

        if target_name == "BR":
            finish_bronze_tasks(
                layer,
                p_ingest_run_id,
                status=final_status,
                log_level=log_level,
                error_message=err,
                audit_offset_base=500
            )
        else:
            finish_layer_tasks(
                layer,
                target_name,
                p_ingest_run_id,
                status=final_status,
                log_level=log_level,
                error_message=err,
                audit_offset_base=600 + idx * 100,
                br_layer=br,
                sl_layer=sl
            )

    payload = {
        "status": "FAILED",
        "mode": mode,
        "failed_target": failed_target,
        "target_layers": ACTIVE_TARGET_LAYERS,
        "terminal_target": TERMINAL_TARGET_NAME,
        "failure_activity": p_failure_activity,
        "message": "Failure audit finalized; raising exception to keep pipeline failed."
    }
    print(json.dumps(payload))
    raise Exception(json.dumps(payload))

else:
    raise Exception(f"Unsupported p_mode: {p_mode}")   

